describe('Dynamic Loading - Hidden Content Reveal', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
  });

  it('should reveal hidden content after asynchronous wait', () => {
    // Verify #finish element is hidden initially
    cy.get('#finish').should('not.be.visible');

    // Click the Start button
    cy.get('#start button').click();

    // Verify loading indicator appears
    cy.get('#loading').should('be.visible');

    // Wait for loading indicator to disappear
    cy.get('#loading', { timeout: 10000 }).should('not.be.visible');

    // Verify #finish element is now visible with correct text
    cy.get('#finish').should('be.visible');
    cy.get('#finish').should('contain.text', 'Hello World!');
  });

  it('should handle rapid consecutive clicks on Start button', () => {
    // Verify initial state
    cy.get('#finish').should('not.be.visible');

    // Click Start button multiple times rapidly
    cy.get('#start button').click();
    cy.get('#start button').click();
    cy.get('#start button').click();

    // Verify loading indicator appears
    cy.get('#loading').should('be.visible');

    // Wait for loading to complete
    cy.get('#loading', { timeout: 10000 }).should('not.be.visible');

    // Verify finish element is visible with correct text
    cy.get('#finish').should('be.visible');
    cy.get('#finish').should('contain.text', 'Hello World!');
  });

  it('should timeout gracefully if loading takes longer than expected', () => {
    cy.get('#finish').should('not.be.visible');

    cy.get('#start button').click();

    cy.get('#loading').should('be.visible');

    // Attempt to wait for loading to disappear with strict timeout
    cy.get('#loading', { timeout: 10000 }).should('not.be.visible');

    // Verify the finish element eventually appears
    cy.get('#finish', { timeout: 10000 }).should('be.visible');
    cy.get('#finish').should('contain.text', 'Hello World!');
  });

  it('should verify loading indicator is present during async operation', () => {
    cy.get('#start button').click();

    // Immediately check that loading is visible
    cy.get('#loading').should('exist');
    cy.get('#loading').should('be.visible');

    // Wait for it to disappear
    cy.get('#loading', { timeout: 10000 }).should('not.be.visible');

    // Confirm finish is now visible
    cy.get('#finish').should('be.visible');
    cy.get('#finish').invoke('text').should('equal', 'Hello World!');
  });
});
